    35→    let sigma_world = gaussian.covariance_matrix();
    36→
    37→    // 4) Rotate covariance into camera space (translation has no effect on covariance).
    38→    let sigma_cam = camera.rotation * sigma_world * camera.rotation.transpose();
    39→
    40→    // 5) Project covariance to 2D via the perspective Jacobian at the mean.
    41→    //
    42→    // Σ₂d = J Σ_cam Jᵀ
    43→    let j = camera.projection_jacobian(&mean_cam);
    44→    let sigma_2d: Matrix2<f32> = j * sigma_cam * j.transpose();
