    46→    // 6) Pack symmetric Σ₂d into (xx, xy, yy). Add a tiny diagonal regularizer for stability.
    47→    let eps = 1e-6;
    48→    let cov_xx = sigma_2d[(0, 0)] + eps;
    49→    let cov_xy = sigma_2d[(0, 1)];
    50→    let cov_yy = sigma_2d[(1, 1)] + eps;
