    52→    // 7) Cull if 2D covariance is degenerate or too large
    53→    // Compute approximate radius: r ≈ sqrt(max(cov_xx, cov_yy))
    54→    // This is a conservative approximation (actual max eigenvalue could be larger)
    55→    let max_cov = cov_xx.max(cov_yy);
