     1→//! Differentiable (CPU) renderer pieces for M7/M8.
     2→//!
     3→//! This file intentionally implements a *minimal* backward pass that only
     4→//! computes gradients w.r.t. Gaussian color (SH coefficients) and opacity,
     5→//! keeping all geometry fixed.
     6→//!
     7→//! Why start here?
     8→//! - It validates the full loss -> pixel gradients -> blend -> per-Gaussian color
     9→//!   gradients pipeline end-to-end.
    10→//! - It is computationally simpler and more stable than immediately optimizing
    11→//!   position/scale/rotation.
    12→//!
    13→//! Next steps (not yet implemented here):
    14→//! - Backprop into 2D covariance / mean (projection math)
    15→//! - Full training loop (M7+)
    16→
    17→use crate::core::{Camera, Gaussian, Gaussian2D};
    18→use crate::diff::blend_grad::{blend_backward_with_bg, blend_forward_with_bg};
    19→use crate::diff::covariance_grad::{
    20→    project_covariance_2d_grad_log_scale, project_covariance_2d_grad_point_cam,
    21→};
    22→use crate::diff::gaussian2d_grad::gaussian2d_evaluate_with_grads;
    23→use crate::diff::project_grad::project_point_grad_point_cam;
    24→use image::RgbImage;
    25→use nalgebra::{Matrix2, Vector2, Vector3};
    26→
    27→fn srgb_u8_to_linear_f32(u: u8) -> f32 {
    28→    let cs = (u as f32) / 255.0;
    29→    if cs <= 0.04045 {
    30→        cs / 12.92
    31→    } else {
    32→        ((cs + 0.055) / 1.055).powf(2.4)
    33→    }
    34→}
    35→
    36→fn linear_f32_to_srgb_u8(x: f32) -> u8 {
    37→    let x = x.clamp(0.0, 1.0);
    38→    let cs = if x <= 0.0031308 {
    39→        12.92 * x
    40→    } else {
    41→        1.055 * x.powf(1.0 / 2.4) - 0.055
    42→    };
    43→    (cs * 255.0).round().clamp(0.0, 255.0) as u8
    44→}
    45→
    46→fn alpha_from_opacity_logit(opacity_logit: f32, weight: f32) -> (f32, f32) {
    47→    let opacity = crate::core::sigmoid(opacity_logit);
    48→    let alpha_raw = opacity * weight;
    49→    let alpha = alpha_raw.min(0.99);
    50→    let d_alpha_d_logit = if alpha_raw < 0.99 {
    51→        weight * opacity * (1.0 - opacity)
    52→    } else {
    53→        0.0
    54→    };
    55→    (alpha, d_alpha_d_logit)
    56→}
    57→
    58→fn project_gaussian(
    59→    gaussian: &Gaussian,
    60→    camera: &Camera,
    61→    gaussian_idx: usize,
    62→    disable_sh: bool,
    63→) -> Option<Gaussian2D> {
    64→    // 1) Transform mean to camera space.
    65→    let mean_cam = camera.world_to_camera(&gaussian.position);
    66→
    67→    // Cull if behind camera OR too close to near plane
    68→    // Near-plane threshold prevents huge splats from divide-by-near-zero in Jacobian
    69→    const NEAR_PLANE: f32 = 0.2; // was 0.01
    70→    if mean_cam.z <= NEAR_PLANE {
    71→        return None;
    72→    }
    73→
    74→    // 2) Project mean to pixel coordinates.
    75→    let mean_px = camera.project(&mean_cam)?;
    76→
    77→    // 3) Reconstruct 3D covariance in world space.
    78→    let sigma_world = gaussian.covariance_matrix();
    79→
    80→    // 4) Rotate covariance into camera space (translation has no effect on covariance).
    81→    let sigma_cam = camera.rotation * sigma_world * camera.rotation.transpose();
    82→
    83→    // 5) Project covariance to 2D via the perspective Jacobian at the mean.
    84→    let j = camera.projection_jacobian(&mean_cam);
    85→    let sigma_2d: Matrix2<f32> = j * sigma_cam * j.transpose();
    86→
    87→    // 6) Pack symmetric Σ₂d into (xx, xy, yy). Add a tiny diagonal regularizer for stability.
    88→    let eps = 1e-6;
    89→    let cov_xx = sigma_2d[(0, 0)] + eps;
    90→    let cov_xy = sigma_2d[(0, 1)];
    91→    let cov_yy = sigma_2d[(1, 1)] + eps;
    92→
    93→    // 7) Cull if 2D covariance is degenerate or too large
    94→    // Compute approximate radius: r ≈ sqrt(max(cov_xx, cov_yy))
    95→    // This is a conservative approximation (actual max eigenvalue could be larger)
    96→    let max_cov = cov_xx.max(cov_yy);
    97→    if !max_cov.is_finite() || max_cov <= 0.0 {
    98→        return None; // Degenerate covariance
    99→    }
   100→
   101→    // Cull if radius would exceed screen dimensions (prevents screen-filling splats)
   102→    let radius_sq = 3.0 * 3.0 * max_cov; // 3-sigma radius squared
   103→    let max_screen_dim = camera.width.max(camera.height) as f32;
   104→    if radius_sq > (max_screen_dim * max_screen_dim) {
   105→        return None; // Too large - would fill screen
   106→    }
   107→
   108→    // Compute color: DC-only when disable_sh is true, full SH otherwise
   109→    let color = if disable_sh {
   110→        crate::core::evaluate_sh_dc_only(&gaussian.sh_coeffs)
   111→    } else {
   112→        crate::core::evaluate_sh_unclamped(
   113→            &gaussian.sh_coeffs,
   114→            &camera.view_direction(&gaussian.position),
   115→        )
   116→    };
   117→
   118→    Some(Gaussian2D {
   119→        mean: Vector3::new(mean_px.x, mean_px.y, mean_cam.z),
   120→        cov: Vector3::new(cov_xx, cov_xy, cov_yy),
   121→        color,
   122→        opacity: crate::core::sigmoid(gaussian.opacity),
   123→        gaussian_idx,
   124→    })
   125→}
   126→
   127→struct Prepared {
   128→    mean_x: f32,
   129→    mean_y: f32,
   130→    cov_xx: f32,
   131→    cov_xy: f32,
   132→    cov_yy: f32,
   133→    inv_xx: f32,
   134→    inv_xy: f32,
   135→    inv_yy: f32,
   136→    opacity: f32,
   137→    color: Vector3<f32>,
   138→    gaussian_idx: usize,
   139→    point_cam: Vector3<f32>,
   140→    min_x: i32,
   141→    max_x: i32,
   142→    min_y: i32,
   143→    max_y: i32,
   144→}
   145→
   146→fn prepare(projected: &[Gaussian2D], gaussians: &[Gaussian], camera: &Camera) -> Vec<Prepared> {
   147→    projected
   148→        .iter()
   149→        .map(|g| {
   150→            let (inv_xx, inv_xy, inv_yy) = g.inverse_covariance();
   151→
   152→            let a = g.cov.x;
   153→            let b = g.cov.y;
   154→            let c = g.cov.z;
   155→            let trace = a + c;
   156→            let disc = ((a - c) * (a - c) + 4.0 * b * b).sqrt();
   157→            let lambda_max = 0.5 * (trace + disc).max(0.0);
   158→
   159→            // 3-sigma conservative bounding circle in pixels.
   160→            let radius = 3.0 * lambda_max.sqrt();
   161→            let min_x = (g.mean.x - radius).floor() as i32;
   162→            let max_x = (g.mean.x + radius).ceil() as i32;
   163→            let min_y = (g.mean.y - radius).floor() as i32;
   164→            let max_y = (g.mean.y + radius).ceil() as i32;
   165→
   166→            Prepared {
   167→                mean_x: g.mean.x,
   168→                mean_y: g.mean.y,
   169→                cov_xx: g.cov.x,
   170→                cov_xy: g.cov.y,
   171→                cov_yy: g.cov.z,
   172→                inv_xx,
   173→                inv_xy,
   174→                inv_yy,
   175→                opacity: g.opacity,
   176→                color: g.color,
   177→                gaussian_idx: g.gaussian_idx,
   178→                point_cam: camera.world_to_camera(&gaussians[g.gaussian_idx].position),
   179→                min_x,
   180→                max_x,
   181→                min_y,
   182→                max_y,
   183→            }
   184→        })
   185→        .collect()
   186→}
   187→
   188→/// Render the image and compute gradients w.r.t. Gaussian RGB color.
   189→///
   190→/// Inputs:
   191→/// - `d_image`: per-pixel upstream gradient dL/d(pixel_rgb) in [0,1] linear space
   192→///
   193→/// Returns:
   194→/// - rendered image (RGB8)
   195→/// - per-Gaussian color gradients (accumulated over pixels)
   196→pub fn render_full_color_grads(
   197→    gaussians: &[Gaussian],
   198→    camera: &Camera,
   199→    d_image: &[Vector3<f32>],
   200→    bg: &Vector3<f32>,
   201→    disable_sh: bool,
   202→) -> (
   203→    RgbImage,
   204→    Vec<Vector3<f32>>,
   205→    Vec<f32>,
   206→    Vec<Vector3<f32>>,
   207→    Vec<Vector3<f32>>,
   208→    Vec<Vector3<f32>>,
   209→    Vector3<f32>,
   210→) {
   211→    let enable_timing = std::env::var("SUGAR_BACKWARD_TIMING").is_ok();
   212→    let t_total = if enable_timing { Some(std::time::Instant::now()) } else { None };
   213→
   214→    let width = camera.width as i32;
   215→    let height = camera.height as i32;
   216→    assert_eq!(d_image.len(), (width * height) as usize);
   217→
   218→    // Project and sort front-to-back.
   219→    let mut projected: Vec<Gaussian2D> = gaussians
   220→        .iter()
   221→        .enumerate()
   222→        .filter_map(|(i, g)| project_gaussian(g, camera, i, disable_sh))
   223→        .collect();
   224→
   225→    // Filter out invalid Gaussians (NaN or inf depth) before sorting
   226→    let original_count = projected.len();
   227→    projected.retain(|g| g.mean.z.is_finite());
   228→    let filtered_count = original_count - projected.len();
   229→    if filtered_count > 0 {
   230→        eprintln!("[CPU WARNING] Filtered {} Gaussians with invalid depth values", filtered_count);
   231→    }
   232→
   233→    projected.sort_by(|a, b| a.mean.z.partial_cmp(&b.mean.z).unwrap());
   234→
   235→    let prepared = prepare(&projected, gaussians, camera);
   236→
   237→    let mut img = RgbImage::new(camera.width, camera.height);
   238→
   239→    // Use parallel iteration for gradient computation with thread-local accumulation
   240→    // to eliminate mutex contention (major speedup!).
   241→    use rayon::prelude::*;
   242→
   243→    // Thread-local gradient accumulation: each thread gets its own gradient buffers
   244→    // and we reduce at the end (much faster than mutex locking on every pixel!).
   245→    struct ThreadLocalGrads {
   246→        d_colors: Vec<Vector3<f32>>,
   247→        d_opacity_logits: Vec<f32>,
   248→        d_mean_px: Vec<Vector2<f32>>,
   249→        d_cov_2d: Vec<Vector3<f32>>,
   250→        d_bg: Vector3<f32>,
   251→    }
   252→
   253→    impl ThreadLocalGrads {
   254→        fn new(num_gaussians: usize) -> Self {
   255→            Self {
   256→                d_colors: vec![Vector3::<f32>::zeros(); num_gaussians],
   257→                d_opacity_logits: vec![0.0f32; num_gaussians],
   258→                d_mean_px: vec![Vector2::<f32>::zeros(); num_gaussians],
   259→                d_cov_2d: vec![Vector3::<f32>::zeros(); num_gaussians],
   260→                d_bg: Vector3::<f32>::zeros(),
   261→            }
   262→        }
   263→    }
   264→
   265→    // Parallel iteration over pixels with thread-local gradient accumulation
   266→    let pixels: Vec<(i32, i32)> = (0..height)
   267→        .flat_map(|py| (0..width).map(move |px| (px, py)))
   268→        .collect();
   269→
   270→    let thread_grads: Vec<ThreadLocalGrads> = pixels
   271→        .par_iter()
   272→        .fold(
   273→            || ThreadLocalGrads::new(gaussians.len()),
   274→            |mut local_grads, &(px, py)| {
   275→                let pixel_x = px as f32 + 0.5;
   276→                let pixel_y = py as f32 + 0.5;
   277→
   278→                // Gather contributing gaussians in depth order for this pixel.
   279→                let mut alphas: Vec<f32> = Vec::new();
   280→                let mut d_alpha_d_logits: Vec<f32> = Vec::new();
   281→                let mut d_alpha_d_weights: Vec<f32> = Vec::new();
   282→                let mut d_weight_d_means: Vec<Vector2<f32>> = Vec::new();
   283→                let mut d_weight_d_covs: Vec<Vector3<f32>> = Vec::new();
   284→                let mut colors: Vec<Vector3<f32>> = Vec::new();
   285→                let mut indices: Vec<usize> = Vec::new();
   286→
   287→                for g in &prepared {
   288→                    if px < g.min_x || px > g.max_x || py < g.min_y || py > g.max_y {
   289→                        continue;
   290→                    }
   291→
   292→                    let det = g.cov_xx * g.cov_yy - g.cov_xy * g.cov_xy;
   293→                    if det <= 1e-10 {
   294→                        continue;
   295→                    }
   296→
   297→                    let w_grads = gaussian2d_evaluate_with_grads(
   298→                        Vector2::new(g.mean_x, g.mean_y),
   299→                        g.cov_xx,
   300→                        g.cov_xy,
   301→                        g.cov_yy,
   302→                        Vector2::new(pixel_x, pixel_y),
   303→                    );
   304→                    let weight = w_grads.value;
   305→
   306→                    let (alpha, d_alpha_d_logit) =
   307→                        alpha_from_opacity_logit(gaussians[g.gaussian_idx].opacity, weight);
   308→                    let opacity = crate::core::sigmoid(gaussians[g.gaussian_idx].opacity);
   309→                    let alpha_raw = opacity * weight;
   310→                    let d_alpha_d_weight = if alpha_raw < 0.99 { opacity } else { 0.0 };
   311→                    if alpha < 1e-4 {
   312→                        continue;
   313→                    }
   314→
   315→                    alphas.push(alpha);
   316→                    d_alpha_d_logits.push(d_alpha_d_logit);
   317→                    d_alpha_d_weights.push(d_alpha_d_weight);
   318→                    d_weight_d_means.push(w_grads.d_mean);
   319→                    d_weight_d_covs.push(Vector3::new(
   320→                        w_grads.d_cov_xx,
   321→                        w_grads.d_cov_xy,
   322→                        w_grads.d_cov_yy,
   323→                    ));
   324→                    colors.push(g.color);
   325→                    indices.push(g.gaussian_idx);
   326→                }
   327→
   328→                let forward = blend_forward_with_bg(&alphas, &colors, bg);
   329→
   330→                // Backward for this pixel
   331→                let upstream = &d_image[(py * width + px) as usize];
   332→                let grads = blend_backward_with_bg(&alphas, &colors, &forward, bg, upstream);
   333→
   334→                // Accumulate into thread-local gradients (no locking!)
   335→                for (k, &gi) in indices.iter().enumerate() {
   336→                    local_grads.d_colors[gi] += grads.d_colors[k];
   337→                    local_grads.d_opacity_logits[gi] += grads.d_alphas[k] * d_alpha_d_logits[k];
   338→                    let d_weight = grads.d_alphas[k] * d_alpha_d_weights[k];
   339→                    local_grads.d_mean_px[gi] += d_weight_d_means[k] * d_weight;
   340→                    local_grads.d_cov_2d[gi] += d_weight_d_covs[k] * d_weight;
   341→                }
   342→                local_grads.d_bg += grads.d_bg;
   343→
   344→                local_grads
   345→            },
   346→        )
   347→        .collect();
   348→
   349→    // Final reduction: combine all thread-local gradients
   350→    let mut d_colors = vec![Vector3::<f32>::zeros(); gaussians.len()];
   351→    let mut d_opacity_logits = vec![0.0f32; gaussians.len()];
   352→    let mut d_mean_px = vec![Vector2::<f32>::zeros(); gaussians.len()];
   353→    let mut d_cov_2d = vec![Vector3::<f32>::zeros(); gaussians.len()];
   354→    let mut d_bg = Vector3::<f32>::zeros();
   355→
   356→    for tg in thread_grads {
   357→        for i in 0..gaussians.len() {
   358→            d_colors[i] += tg.d_colors[i];
   359→            d_opacity_logits[i] += tg.d_opacity_logits[i];
   360→            d_mean_px[i] += tg.d_mean_px[i];
   361→            d_cov_2d[i] += tg.d_cov_2d[i];
   362→        }
   363→        d_bg += tg.d_bg;
   364→    }
   365→
   366→    // Create output image (fast sequential render)
   367→    for py in 0..height {
   368→        for px in 0..width {
   369→            let pixel_x = px as f32 + 0.5;
   370→            let pixel_y = py as f32 + 0.5;
   371→
   372→            let mut alphas_img: Vec<f32> = Vec::new();
   373→            let mut colors_img: Vec<Vector3<f32>> = Vec::new();
   374→
   375→            for g in &prepared {
   376→                if px < g.min_x || px > g.max_x || py < g.min_y || py > g.max_y {
   377→                    continue;
   378→                }
   379→                let dx = pixel_x - g.mean_x;
   380→                let dy = pixel_y - g.mean_y;
   381→                let quad_form = g.inv_xx * dx * dx + 2.0 * g.inv_xy * dx * dy + g.inv_yy * dy * dy;
   382→                let weight = (-0.5 * quad_form).exp();
   383→                let alpha = (g.opacity * weight).min(0.99);
   384→                if alpha < 1e-4 {
   385→                    continue;
   386→                }
   387→                alphas_img.push(alpha);
   388→                colors_img.push(g.color);
   389→            }
   390→
   391→            let out = blend_forward_with_bg(&alphas_img, &colors_img, bg).out;
   392→            img.put_pixel(
   393→                px as u32,
   394→                py as u32,
   395→                image::Rgb([
   396→                    linear_f32_to_srgb_u8(out.x),
   397→                    linear_f32_to_srgb_u8(out.y),
   398→                    linear_f32_to_srgb_u8(out.z),
   399→                ]),
   400→            );
   401→        }
   402→    }
   403→
   404→    let mut d_positions = vec![Vector3::<f32>::zeros(); gaussians.len()];
   405→    let mut d_log_scales = vec![Vector3::<f32>::zeros(); gaussians.len()];
   406→    let mut d_rot_vecs = vec![Vector3::<f32>::zeros(); gaussians.len()];
   407→    for g in &prepared {
   408→        let gi = g.gaussian_idx;
   409→        let mut d_point_cam_total = Vector3::<f32>::zeros();
   410→
   411→        let d_uv = d_mean_px[gi];
   412→        if d_uv != Vector2::zeros() {
   413→            d_point_cam_total +=
   414→                project_point_grad_point_cam(&g.point_cam, camera.fx, camera.fy, &d_uv);
   415→        }
   416→
   417→        let d_cov = d_cov_2d[gi];
   418→        if d_cov != Vector3::zeros() {
   419→            // Backprop through Σ₂d = J(point_cam) Σ_cam Jᵀ into:
   420→            // - point_cam (via Jacobian dependence on depth)
   421→            // - log_scale (via Σ reconstruction)
   422→            // - rotation (via Σ reconstruction)
   423→            let d_sigma2d = Matrix2::new(d_cov.x, d_cov.y, d_cov.y, d_cov.z);
   424→
   425→            let gaussian_r = crate::core::quaternion_to_matrix(&gaussians[gi].rotation);
   426→            let log_scale = gaussians[gi].scale;
   427→
   428→            d_point_cam_total += project_covariance_2d_grad_point_cam(
   429→                &g.point_cam,
   430→                camera.fx,
   431→                camera.fy,
   432→                &camera.rotation,
   433→                &gaussian_r,
   434→                &log_scale,
   435→                &d_sigma2d,
   436→            );
   437→
   438→            let j = camera.projection_jacobian(&g.point_cam);
   439→            d_log_scales[gi] = project_covariance_2d_grad_log_scale(
   440→                &camera.rotation,
   441→                &j,
   442→                &gaussian_r,
   443→                &log_scale,
   444→                &d_sigma2d,
   445→            );
   446→
   447→            d_rot_vecs[gi] = crate::diff::covariance_grad::project_covariance_2d_grad_rotation_vector_at_r0(
   448→                &camera.rotation,
   449→                &j,
   450→                &gaussian_r,
   451→                &log_scale,
   452→                &d_sigma2d,
   453→            );
   454→        }
   455→
   456→        // point_cam = R * p_world + t  =>  dL/dp_world = R^T * dL/dpoint_cam
   457→        d_positions[gi] = camera.rotation.transpose() * d_point_cam_total;
   458→    }
   459→
   460→    (
   461→        img,
   462→        d_colors,
   463→        d_opacity_logits,
   464→        d_positions,
   465→        d_log_scales,
   466→        d_rot_vecs,
   467→        d_bg,
   468→    )
   469→}
   470→
   471→/// Forward render that returns linear RGB pixels in [0,1] (no quantization).
   472→pub fn render_full_linear(
   473→    gaussians: &[Gaussian],
   474→    camera: &Camera,
   475→    bg: &Vector3<f32>,
   476→    disable_sh: bool,
   477→) -> Vec<Vector3<f32>> {
   478→    let width = camera.width as i32;
   479→    let height = camera.height as i32;
   480→    let mut out = vec![Vector3::<f32>::zeros(); (width * height) as usize];
   481→
   482→    let mut projected: Vec<Gaussian2D> = gaussians
   483→        .iter()
   484→        .enumerate()
   485→        .filter_map(|(i, g)| project_gaussian(g, camera, i, disable_sh))
   486→        .collect();
   487→
   488→    // Be robust to upstream numerical issues (e.g., NaN depth after training).
   489→    // If we try to sort with NaNs present, `partial_cmp` returns `None` and panics on unwrap.
   490→    let original_count = projected.len();
   491→    projected.retain(|g| g.mean.z.is_finite());
   492→    let filtered_count = original_count - projected.len();
   493→    if filtered_count > 0 {
   494→        eprintln!(
   495→            "[CPU WARNING] Filtered {} Gaussians with invalid depth values",
   496→            filtered_count
   497→        );
   498→    }
   499→
   500→    projected.sort_by(|a, b| a.mean.z.partial_cmp(&b.mean.z).unwrap());
   501→    let prepared = prepare(&projected, gaussians, camera);
   502→
   503→    for py in 0..height {
   504→        for px in 0..width {
   505→            let pixel_x = px as f32 + 0.5;
   506→            let pixel_y = py as f32 + 0.5;
   507→
   508→            let mut alphas: Vec<f32> = Vec::new();
   509→            let mut colors: Vec<Vector3<f32>> = Vec::new();
   510→
   511→            for g in &prepared {
   512→                if px < g.min_x || px > g.max_x || py < g.min_y || py > g.max_y {
   513→                    continue;
   514→                }
   515→
   516→                let dx = pixel_x - g.mean_x;
   517→                let dy = pixel_y - g.mean_y;
   518→                let quad_form = g.inv_xx * dx * dx + 2.0 * g.inv_xy * dx * dy + g.inv_yy * dy * dy;
   519→                let weight = (-0.5 * quad_form).exp();
   520→                let alpha = (g.opacity * weight).min(0.99);
   521→                if alpha < 1e-4 {
   522→                    continue;
   523→                }
   524→
   525→                alphas.push(alpha);
   526→                colors.push(g.color);
   527→            }
   528→
   529→            out[(py * width + px) as usize] = blend_forward_with_bg(&alphas, &colors, bg).out;
   530→        }
   531→    }
   532→
   533→    out
   534→}
   535→
   536→/// Helper: compute L2 loss gradient w.r.t. rendered pixel colors.
   537→///
   538→/// `rendered` and `target` are linear RGB in [0,1].
   539→pub fn l2_image_grad(
   540→    rendered: &[Vector3<f32>],
   541→    target: &[Vector3<f32>],
   542→) -> (f32, Vec<Vector3<f32>>) {
   543→    assert_eq!(rendered.len(), target.len());
   544→    let n = rendered.len() as f32;
   545→    let mut loss = 0.0f32;
   546→    let mut d = vec![Vector3::<f32>::zeros(); rendered.len()];
   547→
   548→    for i in 0..rendered.len() {
   549→        let diff = rendered[i] - target[i];
   550→        loss += diff.dot(&diff);
   551→        d[i] = diff * (2.0 / n);
   552→    }
   553→    (loss / n, d)
   554→}
