   556→/// Convert an `RgbImage` to linear [0,1] `Vector3` pixels.
   557→pub fn rgb8_to_linear_vec(img: &RgbImage) -> Vec<Vector3<f32>> {
   558→    let mut out = Vec::with_capacity((img.width() * img.height()) as usize);
   559→    for p in img.pixels() {
   560→        out.push(Vector3::new(
   561→            srgb_u8_to_linear_f32(p[0]),
   562→            srgb_u8_to_linear_f32(p[1]),
   563→            srgb_u8_to_linear_f32(p[2]),
   564→        ));
   565→    }
   566→    out
   567→}
