   569→/// Convert linear [0,1] RGB pixels to an `RgbImage` (sRGB encoded).
   570→pub fn linear_vec_to_rgb8_img(linear: &[Vector3<f32>], width: u32, height: u32) -> RgbImage {
   571→    assert_eq!(linear.len(), (width * height) as usize);
   572→    let mut img = RgbImage::new(width, height);
   573→    for (i, p) in linear.iter().enumerate() {
   574→        let x = (i as u32) % width;
   575→        let y = (i as u32) / width;
   576→        img.put_pixel(
   577→            x,
   578→            y,
   579→            image::Rgb([
   580→                linear_f32_to_srgb_u8(p.x),
   581→                linear_f32_to_srgb_u8(p.y),
   582→                linear_f32_to_srgb_u8(p.z),
   583→            ]),
   584→        );
   585→    }
   586→    img
   587→}
   588→
   589→/// Downsample an image using box filter (averaging blocks of pixels).
   590→///
   591→/// This is used for power-of-2 downsampling (divisor = 2, 4, 8, etc.) and provides
   592→/// perfect anti-aliasing with no artifacts.
   593→///
   594→/// IMPORTANT: Averages in linear color space for correct color blending.
   595→///
   596→/// # Arguments
   597→/// * `img` - Source image
   598→/// * `divisor` - Power-of-2 divisor (2, 4, 8, 16, etc.)
   599→///
   600→/// # Returns
   601→/// Downsampled image with dimensions `(img.width() / divisor, img.height() / divisor)`
   602→pub fn downsample_rgb_box(img: &RgbImage, divisor: u32) -> RgbImage {
   603→    let out_width = (img.width() + divisor - 1) / divisor;
   604→    let out_height = (img.height() + divisor - 1) / divisor;
   605→    let mut out = RgbImage::new(out_width, out_height);
   606→
   607→    for out_y in 0..out_height {
   608→        for out_x in 0..out_width {
   609→            let src_x_start = out_x * divisor;
   610→            let src_y_start = out_y * divisor;
   611→            let src_x_end = (src_x_start + divisor).min(img.width());
   612→            let src_y_end = (src_y_start + divisor).min(img.height());
   613→
   614→            // Average all pixels in the block IN LINEAR SPACE
   615→            let mut sum_r = 0.0f32;
   616→            let mut sum_g = 0.0f32;
   617→            let mut sum_b = 0.0f32;
   618→            let mut count = 0u32;
   619→
   620→            for src_y in src_y_start..src_y_end {
   621→                for src_x in src_x_start..src_x_end {
   622→                    let pixel = img.get_pixel(src_x, src_y);
   623→                    // Convert sRGB to linear before averaging
   624→                    sum_r += srgb_u8_to_linear_f32(pixel[0]);
   625→                    sum_g += srgb_u8_to_linear_f32(pixel[1]);
   626→                    sum_b += srgb_u8_to_linear_f32(pixel[2]);
   627→                    count += 1;
   628→                }
   629→            }
   630→
   631→            let count_f = count as f32;
   632→            let avg_r_linear = sum_r / count_f;
   633→            let avg_g_linear = sum_g / count_f;
   634→            let avg_b_linear = sum_b / count_f;
   635→
   636→            // Convert back to sRGB
   637→            out.put_pixel(
   638→                out_x,
   639→                out_y,
   640→                image::Rgb([
   641→                    linear_f32_to_srgb_u8(avg_r_linear),
   642→                    linear_f32_to_srgb_u8(avg_g_linear),
   643→                    linear_f32_to_srgb_u8(avg_b_linear),
   644→                ]),
   645→            );
   646→        }
   647→    }
   648→
   649→    out
   650→}
   651→
   652→/// Downsample an image to match a camera resolution (nearest neighbor, for simplicity).
   653→pub fn downsample_rgb_nearest(img: &RgbImage, width: u32, height: u32) -> RgbImage {
   654→    let mut out = RgbImage::new(width, height);
   655→    let sx = img.width() as f32 / width as f32;
   656→    let sy = img.height() as f32 / height as f32;
   657→    for y in 0..height {
   658→        for x in 0..width {
   659→            let src_x = (x as f32 * sx).floor().clamp(0.0, (img.width() - 1) as f32) as u32;
   660→            let src_y = (y as f32 * sy)
   661→                .floor()
   662→                .clamp(0.0, (img.height() - 1) as f32) as u32;
   663→            let p = *img.get_pixel(src_x, src_y);
   664→            out.put_pixel(x, y, p);
   665→        }
   666→    }
   667→    out
   668→}
   669→
   670→/// Downsample an image using bilinear interpolation in linear color space.
   671→///
   672→/// This produces higher quality results than nearest-neighbor for fractional
   673→/// scaling factors, avoiding aliasing artifacts.
   674→pub fn downsample_rgb_bilinear(img: &RgbImage, target_width: u32, target_height: u32) -> RgbImage {
   675→    use crate::core::color::{linear_f32_to_srgb_u8, srgb_u8_to_linear_f32};
   676→
   677→    let mut out = RgbImage::new(target_width, target_height);
   678→
   679→    let scale_x = img.width() as f32 / target_width as f32;
   680→    let scale_y = img.height() as f32 / target_height as f32;
   681→
   682→    for out_y in 0..target_height {
   683→        for out_x in 0..target_width {
   684→            // Map output pixel center to input space
   685→            let src_x = (out_x as f32 + 0.5) * scale_x - 0.5;
   686→            let src_y = (out_y as f32 + 0.5) * scale_y - 0.5;
   687→
   688→            // Clamp to valid range
   689→            let src_x = src_x.max(0.0).min(img.width() as f32 - 1.0);
   690→            let src_y = src_y.max(0.0).min(img.height() as f32 - 1.0);
   691→
   692→            // Get integer and fractional parts
   693→            let x0 = src_x.floor() as u32;
   694→            let y0 = src_y.floor() as u32;
   695→            let x1 = (x0 + 1).min(img.width() - 1);
   696→            let y1 = (y0 + 1).min(img.height() - 1);
   697→
   698→            let fx = src_x - x0 as f32;
   699→            let fy = src_y - y0 as f32;
   700→
   701→            // Sample 4 neighbors
   702→            let p00 = img.get_pixel(x0, y0);
   703→            let p10 = img.get_pixel(x1, y0);
   704→            let p01 = img.get_pixel(x0, y1);
   705→            let p11 = img.get_pixel(x1, y1);
   706→
   707→            // Bilinear interpolation per channel IN LINEAR SPACE
   708→            let mut result = [0u8; 3];
   709→            for c in 0..3 {
   710→                // Convert sRGB to linear
   711→                let linear_00 = srgb_u8_to_linear_f32(p00[c]);
   712→                let linear_10 = srgb_u8_to_linear_f32(p10[c]);
   713→                let linear_01 = srgb_u8_to_linear_f32(p01[c]);
   714→                let linear_11 = srgb_u8_to_linear_f32(p11[c]);
   715→
   716→                // Bilinear interpolation
   717→                let top = linear_00 * (1.0 - fx) + linear_10 * fx;
   718→                let bottom = linear_01 * (1.0 - fx) + linear_11 * fx;
   719→                let interpolated = top * (1.0 - fy) + bottom * fy;
   720→
   721→                // Convert back to sRGB
   722→                result[c] = linear_f32_to_srgb_u8(interpolated);
   723→            }
   724→
   725→            out.put_pixel(out_x, out_y, image::Rgb(result));
   726→        }
   727→    }
   728→
   729→    out
   730→}
   731→
   732→/// Debug: draw projected Gaussian means as colored dots on top of a target image.
   733→///
   734→/// Uses the same projection and Gaussian subset as the renderer.
   735→pub fn debug_overlay_means(
   736→    target: &RgbImage,
   737→    gaussians: &[Gaussian],
   738→    camera: &Camera,
   739→    radius_px: i32,
   740→) -> RgbImage {
   741→    let width = camera.width as i32;
   742→    let height = camera.height as i32;
   743→    assert_eq!(target.width() as i32, width);
   744→    assert_eq!(target.height() as i32, height);
   745→
   746→    // Project and sort (order doesn't matter for dots, but reuse existing path).
   747→    let mut projected: Vec<Gaussian2D> = gaussians
   748→        .iter()
   749→        .enumerate()
   750→        .filter_map(|(i, g)| project_gaussian(g, camera, i, false))
   751→        .collect();
   752→
   753→    // Filter out invalid Gaussians (NaN or inf depth) before sorting
   754→    projected.retain(|g| g.mean.z.is_finite());
   755→
   756→    projected.sort_by(|a, b| a.mean.z.partial_cmp(&b.mean.z).unwrap());
   757→
   758→    let mut out = target.clone();
   759→    for g in &projected {
   760→        let cx = g.mean.x.round() as i32;
   761→        let cy = g.mean.y.round() as i32;
   762→        let color = [
   763→            linear_f32_to_srgb_u8(g.color.x),
   764→            linear_f32_to_srgb_u8(g.color.y),
   765→            linear_f32_to_srgb_u8(g.color.z),
   766→        ];
   767→
   768→        for dy in -radius_px..=radius_px {
   769→            for dx in -radius_px..=radius_px {
   770→                let x = cx + dx;
   771→                let y = cy + dy;
   772→                if x < 0 || x >= width || y < 0 || y >= height {
   773→                    continue;
   774→                }
   775→                if dx * dx + dy * dy > radius_px * radius_px {
   776→                    continue;
   777→                }
   778→                out.put_pixel(x as u32, y as u32, image::Rgb(color));
   779→            }
   780→        }
   781→    }
   782→    out
   783→}
   784→
   785→#[cfg(test)]
   786→mod tests {
   787→    use super::*;
   788→    use approx::assert_relative_eq;
   789→
   790→    #[test]
   791→    fn test_alpha_from_opacity_logit_matches_finite_difference() {
   792→        let opacity_logit = 0.3f32;
   793→        let weight = 0.7f32;
   794→
   795→        let (_alpha, d_alpha_d_logit) = alpha_from_opacity_logit(opacity_logit, weight);
   796→        assert!(d_alpha_d_logit.is_finite());
   797→
   798→        let eps = 1e-4f32;
   799→        let (alpha_p, _) = alpha_from_opacity_logit(opacity_logit + eps, weight);
   800→        let (alpha_m, _) = alpha_from_opacity_logit(opacity_logit - eps, weight);
   801→        let numerical = (alpha_p - alpha_m) / (2.0 * eps);
   802→
   803→        let diff = (numerical - d_alpha_d_logit).abs();
   804→        assert!(
   805→            diff < 1e-3,
   806→            "finite diff mismatch: numerical={numerical} analytical={d_alpha_d_logit} diff={diff}"
   807→        );
   808→    }
   809→
   810→    #[test]
   811→    fn test_srgb_linear_endpoints() {
   812→        assert_relative_eq!(srgb_u8_to_linear_f32(0), 0.0, epsilon = 1e-6);
   813→        assert_relative_eq!(srgb_u8_to_linear_f32(255), 1.0, epsilon = 1e-6);
   814→        assert_eq!(linear_f32_to_srgb_u8(0.0), 0);
   815→        assert_eq!(linear_f32_to_srgb_u8(1.0), 255);
   816→    }
   817→
   818→    #[test]
   819→    fn test_srgb_midpoint_sanity() {
   820→        // 128/255 ≈ 0.50196 sRGB corresponds to ≈ 0.21586 linear.
   821→        let lin = srgb_u8_to_linear_f32(128);
   822→        assert_relative_eq!(lin, 0.21586, epsilon = 5e-3);
   823→        let back = linear_f32_to_srgb_u8(lin);
   824→        assert!((back as i32 - 128).abs() <= 1);
   825→    }
   826→}
   827→
   828→/// Debug: compute a per-pixel coverage mask (whether any Gaussian contributes).
   829→///
   830→/// The output is a grayscale image where 0=uncovered, 255=covered.
   831→pub fn debug_coverage_mask(gaussians: &[Gaussian], camera: &Camera) -> RgbImage {
   832→    let width = camera.width as i32;
   833→    let height = camera.height as i32;
   834→
   835→    let covered = coverage_mask_bool(gaussians, camera);
   836→    let mut img = RgbImage::new(camera.width, camera.height);
   837→
   838→    for py in 0..height {
   839→        for px in 0..width {
   840→            let v = if covered[(py * width + px) as usize] {
   841→                255u8
   842→            } else {
   843→                0u8
   844→            };
   845→            img.put_pixel(px as u32, py as u32, image::Rgb([v, v, v]));
   846→        }
   847→    }
   848→
   849→    img
   850→}
   851→
   852→/// Compute a per-pixel coverage mask (whether any Gaussian contributes).
   853→///
   854→/// Returns a Vec<bool> with length width*height, row-major.
   855→pub fn coverage_mask_bool(gaussians: &[Gaussian], camera: &Camera) -> Vec<bool> {
   856→    let width = camera.width as i32;
   857→    let height = camera.height as i32;
   858→
   859→    let mut projected: Vec<Gaussian2D> = gaussians
   860→        .iter()
   861→        .enumerate()
   862→        .filter_map(|(i, g)| project_gaussian(g, camera, i, false))
   863→        .collect();
   864→
   865→    // Filter out invalid Gaussians (NaN or inf depth) before sorting
   866→    let original_count = projected.len();
   867→    projected.retain(|g| g.mean.z.is_finite());
   868→    let filtered_count = original_count - projected.len();
   869→    if filtered_count > 0 {
   870→        eprintln!("[CPU WARNING] coverage_mask_bool filtered {} Gaussians with invalid depth values", filtered_count);
   871→    }
   872→
   873→    projected.sort_by(|a, b| a.mean.z.partial_cmp(&b.mean.z).unwrap());
   874→    let prepared = prepare(&projected, gaussians, camera);
   875→
   876→    let mut covered = vec![false; (width * height) as usize];
   877→
   878→    for py in 0..height {
   879→        for px in 0..width {
   880→            let pixel_x = px as f32 + 0.5;
   881→            let pixel_y = py as f32 + 0.5;
   882→
   883→            let mut is_covered = false;
   884→            for g in &prepared {
   885→                if px < g.min_x || px > g.max_x || py < g.min_y || py > g.max_y {
   886→                    continue;
   887→                }
   888→
   889→                let dx = pixel_x - g.mean_x;
   890→                let dy = pixel_y - g.mean_y;
   891→                let quad_form = g.inv_xx * dx * dx + 2.0 * g.inv_xy * dx * dy + g.inv_yy * dy * dy;
   892→                let weight = (-0.5 * quad_form).exp();
   893→                let alpha = (g.opacity * weight).min(0.99);
   894→                if alpha >= 1e-4 {
   895→                    is_covered = true;
   896→                    break;
   897→                }
   898→            }
   899→
   900→            covered[(py * width + px) as usize] = is_covered;
   901→        }
   902→    }
   903→
   904→    covered
   905→}
   906→
   907→/// Compute coverage weights at downsampled resolution and upsample to full resolution.
   908→///
   909→/// This provides a fast approximation of coverage weighting for GPU training,
   910→/// where computing full-resolution coverage on CPU would be too slow.
   911→///
   912→/// Returns a Vec<f32> with length width*height, row-major.
   913→/// Covered pixels get weight 1.0, uncovered pixels get weight 0.5.
   914→/// (0.5 instead of 0.1 to prevent background gradient collapse)
   915→pub fn coverage_weights_downsampled(
   916→    gaussians: &[Gaussian],
   917→    camera: &Camera,
   918→    downsample: u32,
   919→) -> Vec<f32> {
   920→    let full_width = camera.width;
   921→    let full_height = camera.height;
   922→
   923→    // Create downsampled camera
   924→    let ds_width = (full_width + downsample - 1) / downsample;
   925→    let ds_height = (full_height + downsample - 1) / downsample;
   926→    let scale = 1.0 / downsample as f32;
   927→
   928→    let ds_camera = Camera::new(
   929→        camera.fx * scale,
   930→        camera.fy * scale,
   931→        camera.cx * scale,
   932→        camera.cy * scale,
   933→        ds_width,
   934→        ds_height,
   935→        camera.rotation,
   936→        camera.translation,
   937→    );
   938→
   939→    // Compute coverage at low resolution
   940→    let ds_coverage = coverage_mask_bool(gaussians, &ds_camera);
   941→
   942→    // Upsample to full resolution with nearest-neighbor
   943→    // IMPORTANT: Use 0.5 for background pixels (not 0.1) to prevent background gradient vanishing
   944→    let mut weights = vec![0.5f32; (full_width * full_height) as usize];
   945→
   946→    for py in 0..full_height {
   947→        for px in 0..full_width {
   948→            let ds_x = px / downsample;
   949→            let ds_y = py / downsample;
   950→            let ds_idx = (ds_y * ds_width + ds_x) as usize;
   951→
   952→            if ds_idx < ds_coverage.len() && ds_coverage[ds_idx] {
   953→                weights[(py * full_width + px) as usize] = 1.0;
   954→            }
   955→        }
   956→    }
   957→
   958→    weights
   959→}
   960→
   961→/// Debug: visualize the final transmittance `T_N` per pixel (white=transparent, black=opaque).
   962→pub fn debug_final_transmittance(gaussians: &[Gaussian], camera: &Camera) -> RgbImage {
   963→    let width = camera.width as i32;
   964→    let height = camera.height as i32;
   965→
   966→    let mut projected: Vec<Gaussian2D> = gaussians
   967→        .iter()
   968→        .enumerate()
   969→        .filter_map(|(i, g)| project_gaussian(g, camera, i, false))
   970→        .collect();
   971→
   972→    // Filter out invalid Gaussians (NaN or inf depth) before sorting
