   982→            let pixel_x = px as f32 + 0.5;
   983→            let pixel_y = py as f32 + 0.5;
   984→
   985→            let mut t = 1.0f32;
   986→            for g in &prepared {
   987→                if px < g.min_x || px > g.max_x || py < g.min_y || py > g.max_y {
   988→                    continue;
   989→                }
   990→
   991→                let dx = pixel_x - g.mean_x;
   992→                let dy = pixel_y - g.mean_y;
   993→                let quad_form = g.inv_xx * dx * dx + 2.0 * g.inv_xy * dx * dy + g.inv_yy * dy * dy;
   994→                let weight = (-0.5 * quad_form).exp();
   995→                let alpha = (g.opacity * weight).min(0.99);
   996→                if alpha < 1e-4 {
   997→                    continue;
   998→                }
   999→                t *= 1.0 - alpha;
  1000→            }
  1001→
  1002→            let v = linear_f32_to_srgb_u8(t);
  1003→            img.put_pixel(px as u32, py as u32, image::Rgb([v, v, v]));
  1004→        }
  1005→    }
  1006→
  1007→    img
  1008→}
