            }
            "--camera-id" => {
                let id_str = args.next().expect("Missing --camera-id argument");
                camera_id = Some(id_str.parse().expect("Invalid camera ID"));
            }
            "--camera-json" => {
                camera_json = Some(PathBuf::from(
