                ));
            }
            "--dataset-root" => {
                dataset_root = Some(PathBuf::from(
                    args.next().expect("Missing --dataset-root argument"),
                ));
            }
            "--out" => {
                out_path = PathBuf::from(args.next().expect("Missing --out argument"));
            }
