     4→//!   sugar-render --model model.gs --camera-id 0 --dataset-root path/to/colmap --out render.png
     5→//!   sugar-render --model model.gs --camera-json camera.json --out render.png
     6→
     7→use sugar_rs::core::{quaternion_to_matrix, Camera};
     8→use sugar_rs::io::{load_colmap_scene, load_model};
     9→use sugar_rs::render::full_diff::{linear_vec_to_rgb8_img, render_full_linear};
    10→use nalgebra::Vector3;
