    12→
    13→fn main() {
    14→    println!("sugar-render v{}", sugar_rs::VERSION);
    15→
    16→    // Parse command-line arguments
    17→    let mut args = std::env::args().skip(1);
    18→    let mut model_path: Option<PathBuf> = None;
    19→    let mut camera_id: Option<usize> = None;
    20→    let mut camera_json: Option<PathBuf> = None;
    21→    let mut dataset_root: Option<PathBuf> = None;
    22→    let mut out_path: PathBuf = PathBuf::from("render.png");
    23→    let mut background: Vector3<f32> = Vector3::new(0.0, 0.0, 0.0);
