/// Forward render that returns linear RGB pixels in [0,1] (no quantization).
pub fn render_full_linear(
    gaussians: &[Gaussian],
    camera: &Camera,
    bg: &Vector3<f32>,
    disable_sh: bool,
) -> Vec<Vector3<f32>> {
    render_full_linear_with_depth(gaussians, camera, bg, disable_sh).0
}

/// Forward render that returns both linear RGB pixels and depth values.
/// Returns (rgb_pixels, depth_pixels) where depth is in camera space Z coordinate.
pub fn render_full_linear_with_depth(
    gaussians: &[Gaussian],
    camera: &Camera,
    bg: &Vector3<f32>,
    disable_sh: bool,
) -> (Vec<Vector3<f32>>, Vec<f32>) {
    let width = camera.width as i32;
    let height = camera.height as i32;
    let mut out_rgb = vec![Vector3::<f32>::zeros(); (width * height) as usize];
    let mut out_depth = vec![0.0f32; (width * height) as usize];

    let mut projected: Vec<Gaussian2D> = gaussians
        .iter()
        .enumerate()
        .filter_map(|(i, g)| project_gaussian(g, camera, i, disable_sh))
        .collect();

    // Be robust to upstream numerical issues (e.g., NaN depth after training).
    // If we try to sort with NaNs present, `partial_cmp` returns `None` and panics on unwrap.
    let original_count = projected.len();
    projected.retain(|g| g.mean.z.is_finite());
    let filtered_count = original_count - projected.len();
    if filtered_count > 0 {
        eprintln!(
            "[CPU WARNING] Filtered {} Gaussians with invalid depth values",
            filtered_count
        );
    }

    projected.sort_by(|a, b| a.mean.z.partial_cmp(&b.mean.z).unwrap());
    let prepared = prepare(&projected, gaussians, camera);

    for py in 0..height {
        for px in 0..width {
            let pixel_x = px as f32 + 0.5;
            let pixel_y = py as f32 + 0.5;

            let mut alphas: Vec<f32> = Vec::new();
            let mut colors: Vec<Vector3<f32>> = Vec::new();
            let mut depths: Vec<f32> = Vec::new();

            for (idx, g) in prepared.iter().enumerate() {
                if px < g.min_x || px > g.max_x || py < g.min_y || py > g.max_y {
                    continue;
                }

                let dx = pixel_x - g.mean_x;
                let dy = pixel_y - g.mean_y;
                let quad_form = g.inv_xx * dx * dx + 2.0 * g.inv_xy * dx * dy + g.inv_yy * dy * dy;
                let weight = (-0.5 * quad_form).exp();
                let alpha = (g.opacity * weight).min(0.99);
                if alpha < 1e-4 {
                    continue;
                }

                alphas.push(alpha);
                colors.push(g.color);
                // Use depth from projected Gaussians (camera space Z)
                depths.push(projected[idx].mean.z);
            }

            let pixel_idx = (py * width + px) as usize;
            out_rgb[pixel_idx] = blend_forward_with_bg(&alphas, &colors, bg).out;

            // Accumulate depth using same front-to-back alpha compositing as color
            let mut depth_accum = 0.0f32;
            let mut transmittance = 1.0f32;
            for i in 0..alphas.len() {
                depth_accum += transmittance * alphas[i] * depths[i];
                transmittance *= 1.0 - alphas[i];
            }
            out_depth[pixel_idx] = depth_accum;
        }
    }

    (out_rgb, out_depth)
}

